"""Shared DOM renderer for source requests; never executes patient actions."""
SCRIPT = r'''
function renderProgramAcquisition(parent,r,fetchJSON){
 const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e},pretty=s=>s.replaceAll('_',' '),detail=(title,obj)=>{const e=node('details');e.append(node('summary',title),node('pre',JSON.stringify(obj,null,2)));return e};
 parent.append(node('h2','What would resolve the answer?'),node('p',r.patients_evaluated.toLocaleString()+' synthetic patients · '+r.counts.specification_requests+' shared specification requests · '+r.counts.patient_requests.toLocaleString()+' patient evidence requests'),node('p',r.counts.patients_with_conditional_requests.toLocaleString()+' patients have inputs that could change an unresolved predicate. These are hypothetical conditions, not predicted outcomes or missing-care findings.'));
 const queue=node('div'),more=node('button','Read shared mapping and patient requests');let offset=0;
 more.onclick=async()=>{more.disabled=true;try{const page=await fetchJSON('/api/stack/program-acquisition?id='+r.id+'&offset='+offset);for(const item of page.items){const box=node('section');box.append(node('h3',(item.patient_id||'Shared specification')+' · '+pretty(item.kind)),node('p',item.instruction),node('p',item.patients_with_dependency.length+' source dependencies · '+item.patients_with_conditional_impact.length+' conditional impacts'),detail('Exact requirement, source and affected patients',item));queue.append(box)}if(page.next_offset===null)more.remove();else {offset=page.next_offset;more.textContent='Read more patient evidence requests'}}catch(e){queue.append(node('p',e.message))}finally{more.disabled=false}};
 const form=node('form'),label=node('label','Inspect a synthetic patient’s conditional evidence'),input=node('input');input.required=true;input.maxLength=150;label.append(input);const inspect=node('button','Inspect conditions and source');inspect.type='submit';const patient=node('div');form.append(label,inspect);
 form.onsubmit=async e=>{e.preventDefault();inspect.disabled=true;try{const d=await fetchJSON('/api/stack/program-acquisition?id='+r.id+'&patient='+encodeURIComponent(input.value)),p=d.resolution;if(p.patient_id!==input.value)throw Error('Patient mismatch');patient.replaceChildren(node('h3',p.patient_id+' · '+pretty(p.status)),node('p',pretty(p.resolution.status)));if(p.resolution.reason)patient.append(node('p',p.resolution.reason));for(const c of p.resolution.cases){const names=Object.keys(c.source_values),condition=names.length?names.map(k=>p.variables[k].input_names.join(' / ')+' source condition = '+c.source_values[k]).join(' AND '):'Current received inputs';patient.append(node('p',condition+' → quoted predicate '+c.program_value),detail('Mapped input values and requests',c))}for(const req of p.requests)patient.append(node('h3',pretty(req.kind)),node('p',req.instruction));patient.append(detail('Patient source receipts, exact quotes and conditional derivation',d))}catch(err){patient.replaceChildren(node('p',err.message))}finally{inspect.disabled=false}};
 parent.append(more,queue,form,patient,detail('Complete population and local reuse',r));
}
'''
